insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('c9378548-e134-5376-b77b-537913eaa3ef'::uuid,1,'What do you admire about the way another person handles change?','what do you admire about the way another person handles change','{}'::jsonb,'published','Initial deterministic bundled-content import'),
