  ('ab220477-897a-571d-9090-b9a92072c335'::uuid,1,'What do you hope people here never doubt about their importance to you?','what do you hope people here never doubt about their importance to you','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('46ad2314-1151-5d84-b0eb-3dbc4362b37f'::uuid,1,'When has being known by this family felt like a gift?','when has being known by this family felt like a gift','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('2b1cc6a8-bfa4-5b45-a1e8-a9862b732ca4'::uuid,1,'What is one thank-you that would be meaningful to say while there is time?','what is one thank you that would be meaningful to say while there is time','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('65ba8a0d-2edf-535c-b1e4-ff8580d84a9e'::uuid,1,'Which part of our connection feels stronger than it did a year ago?','which part of our connection feels stronger than it did a year ago','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('50e013b7-b267-5feb-a893-64fc17b521f3'::uuid,1,'What is the most family-specific joke that would confuse an outsider?','what is the most family specific joke that would confuse an outsider','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('8ea15c17-5e12-562b-8a7a-6ee90725fc08'::uuid,1,'Who here would be the funniest narrator of a nature documentary?','who here would be the funniest narrator of a nature documentary','{}'::jsonb,'published','Initial deterministic bundled-content import'),
