  ('3c6a38d1-12c2-5fae-97c4-aea0ae33159d'::uuid,1,'What ridiculous disagreement from the past can everyone laugh about now?','what ridiculous disagreement from the past can everyone laugh about now','{}'::jsonb,'published','Initial deterministic bundled-content import'),
