insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('671477ed-1ca1-5e42-b206-fc9e9bb7648a'::uuid,1,'They leave group gatherings when someone becomes disrespectful.','they leave group gatherings when someone becomes disrespectful','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e8acd9c9-a47f-5567-8caa-09280f7eb3c7'::uuid,1,'They maintain a friendship with someone who openly dislikes you.','they maintain a friendship with someone who openly dislikes you','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('525954ef-7b16-50c8-b90b-bf1293170475'::uuid,1,'They want future children to grow up near extended family.','they want future children to grow up near extended family','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('32e47b24-b52b-5a55-a8dc-b520258c2e6c'::uuid,1,'They avoid introducing you to one complicated relative.','they avoid introducing you to one complicated relative','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('a79048f5-3573-5cf3-a91f-19ed9211659f'::uuid,1,'They are everyone’s emergency contact and struggle to say no.','they are everyone''s emergency contact and struggle to say no','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('4084d018-6dc1-5344-9c81-03d9bcd75143'::uuid,1,'They welcome your friends but need advance notice before visits.','they welcome your friends but need advance notice before visits','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('2d01b5cf-3a9e-51e5-8ce8-57c16318a75c'::uuid,1,'They post photographs of you only after asking.','they post photographs of you only after asking','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('ca2f6663-ec77-59fc-9cde-2cc44d63d668'::uuid,1,'They never update their public relationship status.','they never update their public relationship status','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('30dcf376-cce3-55a4-9ff6-e44512abaa66'::uuid,1,'They share affectionate posts after every disagreement.','they share affectionate posts after every disagreement','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('b771d4d2-8872-5e62-877f-3dc99fd9463c'::uuid,1,'They use their phone throughout meals but respond when addressed.','they use their phone throughout meals but respond when addressed','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('a280e034-d0d0-5629-b803-4103eec6e832'::uuid,1,'They follow former partners and occasionally like their updates.','they follow former partners and occasionally like their updates','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d0d38577-8e29-5825-9a46-b356b8d403df'::uuid,1,'They prefer private messages to public birthday posts.','they prefer private messages to public birthday posts','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('f625c9da-fb09-58e0-8d5c-071194ddabbb'::uuid,1,'They comment flirtatiously on friends’ photographs as a running joke.','they comment flirtatiously on friends'' photographs as a running joke','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6ac62767-6f38-51c4-b017-0b8b85c32d0b'::uuid,1,'They archive couple photos after an argument.','they archive couple photos after an argument','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e0af9829-f82a-5f08-8c79-f9df29623857'::uuid,1,'They record special moments before fully experiencing them.','they record special moments before fully experiencing them','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e558d097-61c4-5f32-97ae-6290de2a78ac'::uuid,1,'They ask you to remove an unflattering photo of them.','they ask you to remove an unflattering photo of them','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d8670326-afab-5c19-af8e-a3eb65b3f851'::uuid,1,'They share indirect quotes online when upset.','they share indirect quotes online when upset','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('2f28352a-9f53-5cc5-9cb1-4e32e24f4d9f'::uuid,1,'They have thousands of followers but keep relationships private.','they have thousands of followers but keep relationships private','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('bcfbaca9-75e4-5a55-b032-1e6929bfb18c'::uuid,1,'They expect quick replies because they can see you are online.','they expect quick replies because they can see you are online','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('1787ea55-1974-52be-afb2-1b487a9efd8c'::uuid,1,'They turn off read receipts to reduce communication pressure.','they turn off read receipts to reduce communication pressure','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('9421072a-7f54-540b-8e41-98ab7951cefb'::uuid,1,'They tag your location while you are still there.','they tag your location while you are still there','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('edeb7fb2-636e-56c4-bfd6-25c81b1c77d3'::uuid,1,'They keep notifications hidden on their lock screen.','they keep notifications hidden on their lock screen','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('47c5505a-4ee5-5536-830a-59fe205a652b'::uuid,1,'They post jokes about relationships that resemble your private issues.','they post jokes about relationships that resemble your private issues','{}'::jsonb,'published','Initial deterministic bundled-content import'),
