  ('7ed819f8-cd0a-553b-a9e0-9a161a6fe7bd'::uuid,1,'Where might you leave more room for an answer unlike your own?','where might you leave more room for an answer unlike your own','{}'::jsonb,'published','Initial deterministic bundled-content import'),
