insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) values
  ('12cd6a63-6ab0-5dcc-a43d-1c057e2c68db'::uuid,1,'Act out hearing your favorite song from across a crowded venue. Or drink.','act out hearing your favorite song from across a crowded venue or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('39d514e4-4ac9-576a-bd23-47e8d7fdfaa4'::uuid,1,'Pretend a tiny parade is crossing the table and describe what you see. Or drink.','pretend a tiny parade is crossing the table and describe what you see or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('401dffaf-54fd-5601-98ed-373168c1c47d'::uuid,1,'Mime taking the perfect group photo with an imaginary camera. Or drink.','mime taking the perfect group photo with an imaginary camera or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('5f7b4d78-63e0-5484-8f70-0e84a1bbdf87'::uuid,1,'Act out trying to leave a party while saying five separate goodbyes. Or drink.','act out trying to leave a party while saying five separate goodbyes or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('60a4cc23-eae2-515e-acb9-b3ade525b283'::uuid,1,'Pretend you are the calm coordinator of a celebration in zero gravity. Or drink.','pretend you are the calm coordinator of a celebration in zero gravity or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('5ca07656-c6fd-533d-9a84-0b01d37f11ff'::uuid,1,'Strike three different poses for an imaginary party photographer. Or drink.','strike three different poses for an imaginary party photographer or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('8f258daa-b87c-5d30-9ed2-3c8cfd9f475a'::uuid,1,'Model an imaginary outfit designed for a celebration on the moon. Or drink.','model an imaginary outfit designed for a celebration on the moon or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('d8d7865c-5c27-5012-80d8-7f5bf6f1fb59'::uuid,1,'Create a red-carpet pose inspired by your favorite snack. Or drink.','create a red carpet pose inspired by your favorite snack or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('4ae81d19-199a-5507-b4f8-098464fe3d50'::uuid,1,'Walk five steps as though your outfit has its own theme music. Or drink.','walk five steps as though your outfit has its own theme music or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('95be54ac-7339-581c-9b89-1ea4b3b14e8a'::uuid,1,'Show the group your friendliest arrival pose and your sleepiest departure pose. Or drink.','show the group your friendliest arrival pose and your sleepiest departure pose or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('cbe88f5d-3bc1-5598-97d6-18c046299fcd'::uuid,1,'Invent a signature wave for entering a glamorous party. Or drink.','invent a signature wave for entering a glamorous party or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('e705ff0c-c9e1-52bc-8fbe-cb0f0543a763'::uuid,1,'Pose like the centerpiece in an elaborate party display. Or drink.','pose like the centerpiece in an elaborate party display or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('a46445ab-58b1-5b67-8fc4-5dbef278952f'::uuid,1,'Demonstrate how three fictional characters would enter this room. Or drink.','demonstrate how three fictional characters would enter this room or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('6191bbce-3f38-501e-b8d5-3e2717eabbd4'::uuid,1,'Create a runway walk for an outfit made entirely of imaginary streamers. Or drink.','create a runway walk for an outfit made entirely of imaginary streamers or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('5e5db77a-4702-50cb-ad7a-bcf758fdd47c'::uuid,1,'Hold a dramatic album-cover pose while the group counts to five. Or drink.','hold a dramatic album cover pose while the group counts to five or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
  ('db6d1e40-e371-50bc-8e5d-568ea9da42e3'::uuid,1,'Show your best pose for a photo taken just as confetti falls. Or drink.','show your best pose for a photo taken just as confetti falls or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
