  ('9fe00204-b41c-5fa7-a9ee-65237dba6244'::uuid,1,'Make a slow-motion entrance from your seat to the center of the room. Or drink.','make a slow motion entrance from your seat to the center of the room or drink','{}'::jsonb,'published','Initial deterministic bundled-content import'),
